{
  "stimulus": null,
  "item": {
    "stem": "En la proporción directa 12 / 84 = 18 / x, ¿cuál es el valor de x?",
    "context": {
      "kind": "ABSTRACT",
      "description": "Relación numérica abstracta entre dos cantidades directamente proporcionales."
    },
    "declaredModel": {
      "construct": "DIRECT_PROPORTION_MISSING_VALUE",
      "parameters": {
        "a": 12,
        "b": 84,
        "c": 18
      }
    },
    "selected": {
      "options": [
        {
          "id": "A",
          "text": "126"
        },
        {
          "id": "B",
          "text": "102"
        },
        {
          "id": "C",
          "text": "2.57"
        },
        {
          "id": "D",
          "text": "56"
        }
      ],
      "answerKey": "A",
      "distractors": {
        "B": {
          "misconceptionModelId": "additive",
          "rationale": "Suma 84 y 18 en lugar de conservar la razón constante entre las cantidades."
        },
        "C": {
          "misconceptionModelId": "inverted",
          "rationale": "Invierte la relación y calcula 12 × 18 / 84, que no corresponde a x = 84 × 18 / 12."
        },
        "D": {
          "misconceptionModelId": "wrong-pair",
          "rationale": "Forma la combinación incorrecta 12 × 84 / 18 y no despeja el cuarto valor de la proporción."
        }
      },
      "target": {
        "kind": "QUANTITY",
        "quantity": "MISSING_VALUE"
      },
      "answerCheck": {
        "kind": "ARITHMETIC_EXPRESSION",
        "expression": "84*18/12"
      }
    },
    "numeric": null,
    "constructed": null,
    "credit": null,
    "rationale": "Para mantener constante la razón, se despeja x: x = 84 × 18 / 12 = 126.",
    "usesStimulusValues": null,
    "proposedSupportingConceptStableIds": []
  }
}

{
  "stimulus": null,
  "item": {
    "stem": "A model for the output Q units of a process is Q = (20 + 2x)(50 - x), where x is a free measure satisfying 0 <= x <= 50. Find the quadratic expression for Q, then find the value of x that gives the maximum output and the maximum output itself. State what your answers mean in this situation.",
    "context": {
      "kind": "SCIENTIFIC",
      "description": "A mathematical model represents the output of a process as the product of two linear factors."
    },
    "declaredModel": {
      "construct": "QUADRATIC_MODEL_VERTEX_OPTIMUM",
      "parameters": {
        "p": 20,
        "q": 2,
        "r": 50,
        "s": 1
      }
    },
    "selected": null,
    "numeric": null,
    "constructed": {
      "parts": [
        {
          "label": "a",
          "prompt": "Find the quadratic expression for Q in terms of x.",
          "marks": 2,
          "markScheme": [
            {
              "kind": "METHOD",
              "marks": 1,
              "criterion": "Expands the product of the two linear factors correctly."
            },
            {
              "kind": "ACCURACY",
              "marks": 1,
              "criterion": "Obtains Q = -2x^2 + 80x + 1000."
            }
          ],
          "finalAnswer": "Q = -2x^2 + 80x + 1000",
          "numericKey": null,
          "target": {
            "kind": "NOT_MACHINE_CHECKABLE",
            "reason": "The response is an algebraic quadratic expression rather than one named numerical quantity."
          },
          "answerCheck": {
            "kind": "NOT_COMPUTABLE",
            "reason": "Equivalent expanded or factored algebraic forms are acceptable."
          }
        },
        {
          "label": "b",
          "prompt": "Find the value of x at which Q is maximized.",
          "marks": 3,
          "markScheme": [
            {
              "kind": "METHOD",
              "marks": 2,
              "criterion": "Uses the vertex of the quadratic, for example x = -b/(2a), with a = -2 and b = 80."
            },
            {
              "kind": "ACCURACY",
              "marks": 1,
              "criterion": "Obtains x = 20."
            }
          ],
          "finalAnswer": "x = 20",
          "numericKey": {
            "kind": "NUMERIC",
            "value": "20",
            "equivalentFormsAllowed": true
          },
          "target": {
            "kind": "QUANTITY",
            "quantity": "MEASURE_AT_OPTIMUM"
          },
          "answerCheck": {
            "kind": "ARITHMETIC_EXPRESSION",
            "expression": "80/(2*2)"
          }
        },
        {
          "label": "c",
          "prompt": "Find the maximum value of Q and state the meaning of both optimal answers in the situation.",
          "marks": 3,
          "markScheme": [
            {
              "kind": "METHOD",
              "marks": 1,
              "criterion": "Substitutes x = 20 into the model or evaluates the two factors at x = 20."
            },
            {
              "kind": "ACCURACY",
              "marks": 1,
              "criterion": "Obtains Q = 1800."
            },
            {
              "kind": "REASONING",
              "marks": 1,
              "criterion": "States that choosing x = 20 gives the greatest possible output, which is 1800 units."
            }
          ],
          "finalAnswer": "The maximum output is Q = 1800 units, reached when x = 20.",
          "numericKey": {
            "kind": "NUMERIC",
            "value": "1800",
            "equivalentFormsAllowed": true
          },
          "target": {
            "kind": "QUANTITY",
            "quantity": "OPTIMAL_VALUE"
          },
          "answerCheck": {
            "kind": "ARITHMETIC_EXPRESSION",
            "expression": "(20+2*20)*(50-20)"
          }
        }
      ],
      "totalMarks": 8,
      "workingOutline": [
        "Expand Q = (20 + 2x)(50 - x) to obtain the quadratic expression.",
        "Use the vertex formula for the quadratic to find the maximizing value x = 20.",
        "Substitute x = 20 into the original model to calculate Q = 1800.",
        "Interpret x = 20 as the optimal free measure and Q = 1800 as the maximum output."
      ]
    },
    "credit": null,
    "rationale": null,
    "usesStimulusValues": null,
    "proposedSupportingConceptStableIds": []
  }
}

{
  "stimulus": null,
  "item": {
    "stem": "Una bolsa contiene 12 fichas, de las cuales 3 son verdes. Si se extrae una ficha al azar y todas las fichas tienen la misma probabilidad de ser extraídas, ¿cuál es la probabilidad de extraer una ficha verde?",
    "context": {
      "kind": "PERSONAL",
      "description": "Una persona extrae una ficha de una bolsa para conocer la probabilidad de obtener una ficha verde."
    },
    "declaredModel": {
      "construct": "CLASSICAL_PROBABILITY_SINGLE_DRAW",
      "parameters": {
        "n": 12,
        "k": 3
      }
    },
    "selected": {
      "options": [
        {
          "id": "A",
          "text": "1/4"
        },
        {
          "id": "B",
          "text": "1/3"
        },
        {
          "id": "C",
          "text": "3/4"
        },
        {
          "id": "D",
          "text": "1/12"
        }
      ],
      "answerKey": "A",
      "distractors": {
        "B": {
          "misconceptionModelId": "odds",
          "rationale": "Usa las fichas no verdes como denominador y calcula 3/(12-3), que corresponde a las probabilidades relativas, no a la probabilidad clásica del evento."
        },
        "C": {
          "misconceptionModelId": "complement",
          "rationale": "Calcula la probabilidad del complemento, es decir, de no obtener una ficha verde: 1-3/12=3/4."
        },
        "D": {
          "misconceptionModelId": "categories",
          "rationale": "Toma una sola ficha favorable como si fuera el evento completo y divide 1 entre el total, ignorando que hay 3 fichas verdes."
        }
      },
      "target": {
        "kind": "QUANTITY",
        "quantity": "PROBABILITY"
      },
      "answerCheck": {
        "kind": "ARITHMETIC_EXPRESSION",
        "expression": "3/12"
      }
    },
    "numeric": null,
    "constructed": null,
    "credit": null,
    "rationale": "La probabilidad clásica se obtiene dividiendo el número de resultados favorables entre el número total de resultados igualmente probables: P=3/12=1/4.",
    "usesStimulusValues": null,
    "proposedSupportingConceptStableIds": []
  }
}
